#[derive(Default)]
struct Source { records: BTreeMap<u32, Value>, changed: BTreeSet<u32>, requests: Vec<String>, fault: Option<&'static str> }
type Shared = Arc<Mutex<Source>>;
async fn interests(State(state): State<Shared>, OriginalUri(uri): OriginalUri) -> Response {
    let mut source = state.lock().unwrap();
    source.requests.push(uri.to_string());
    let url = reqwest::Url::parse(&format!("http://localhost{uri}")).unwrap();
    let query = url.query_pairs().into_owned().collect::<BTreeMap<_, _>>();
    if source.fault == Some("http") { return StatusCode::SERVICE_UNAVAILABLE.into_response(); }
    let skip = query["Skip"].parse::<usize>().unwrap();
    let take = query["Take"].parse::<usize>().unwrap();
    let discovery = query.contains_key("PublishedFrom") || query.contains_key("UpdatedFrom");
    let mut items = source.records.iter().filter(|(id, value)| {
        if let Some(member) = query.get("MemberId") { value["registrant"]["memberDetail"]["id"].as_u64() == Some(member.parse().unwrap()) }
        else if let Some(requested) = query.get("InterestIds") { **id == requested.parse::<u32>().unwrap() }
        else { source.changed.contains(id) }
    }).map(|(_, value)| value.clone()).collect::<Vec<_>>();
    if discovery {
        for value in &mut items { let last = value["versions"].as_array().unwrap()[0].clone(); value["versions"] = json!([last]); }
    }
    let total = items.len();
    let mut page = items.into_iter().skip(skip).take(take).collect::<Vec<_>>();
    if discovery && source.fault == Some("duplicate") && skip > 0 && !page.is_empty() { page[0] = source.records[&1].clone(); }
    if discovery && source.fault == Some("truncated") && skip > 0 { page.clear(); }
    let total = if discovery && source.fault == Some("total") && skip > 0 { total + 1 } else { total };
    Json(json!({"items": page, "totalResults": total})).into_response()
}

