fn company(name: &str, amount: &str) -> Value { json!([{"name":"DonorName", "value":name}, {"name":"DonorStatus", "value":"Company"}, {"name":"DonorCompanyIdentifier", "value":"00001234"}, {"name":"Value", "value":amount}]) }
fn child(amount: &str) -> Value { json!([{"name":"IsUltimatePayerDifferent", "value":false}, {"name":"Value", "value":amount}]) }

async fn cli(pool: &PgPool, config: &Path, stage: &str, resume: Option<Uuid>) -> std::process::Output {
    let options = pool.connect_options();
    let url = format!("postgresql://{}:{}@{}:{}/{}?sslmode=disable", options.get_username(), options.get_password().unwrap_or_default(), options.get_host(), options.get_port(), options.get_database().unwrap());
    let config = config.to_owned();
    let stage = stage.to_owned();
    tokio::task::spawn_blocking(move || {
        let mut command = std::process::Command::new(env!("CARGO_BIN_EXE_exposed"));
        command.args(["data", "declarations", &stage, "--config"]).arg(config).env("DATABASE_URL", url);
        if let Some(run) = resume { command.args(["--resume", &run.to_string()]); }
        command.output().unwrap()
    }).await.unwrap()
}
fn success(output: std::process::Output) { assert!(output.status.success(), "stdout={} stderr={}", String::from_utf8_lossy(&output.stdout), String::from_utf8_lossy(&output.stderr)); }
async fn head(pool: &PgPool) -> (Uuid, i64, String) {
    let row = sqlx::query!("SELECT run.ingestion_key, run.revision, run.coverage_date::text AS \"date!\" FROM exposed.declaration_sync_head head JOIN exposed.declaration_sync_runs run USING (ingestion_key)").fetch_one(pool).await.unwrap();
    (row.ingestion_key, row.revision, row.date)
}
async fn projection(pool: &PgPool) -> Value {
    sqlx::query_scalar!(r#"SELECT jsonb_build_object(
        'declarations', (SELECT jsonb_agg(jsonb_build_array(source_declaration_id, member_id, category_id, category_name, registration_date) ORDER BY source_declaration_id) FROM exposed.declarations),
        'entries', (SELECT jsonb_agg(jsonb_build_array(e.source_declaration_id, e.amount, e.currency, e.payment_type, f.funder_name, f.company_number, e.attribution_basis, e.selected_parent_declaration_id, e.unavailable_reason, e.attribution_issues) ORDER BY e.source_declaration_id, e.source_funding_entry_id) FROM exposed.funding_entries e LEFT JOIN exposed.funders f ON f.id = e.funder_id),
        'aliases', (SELECT jsonb_agg(jsonb_build_array(f.company_number, a.funder_alias) ORDER BY f.company_number, a.funder_alias) FROM exposed.funder_aliases a JOIN exposed.funders f ON f.id = a.funder_id),
        'groups', (SELECT jsonb_agg(jsonb_build_array(f.funder_name, g.group_id = g.funder_id) ORDER BY f.funder_name) FROM exposed.funder_group_members g JOIN exposed.funders f ON f.id = g.funder_id)
    ) AS "projection!""#).fetch_one(pool).await.unwrap()
}
fn copy_directory(source: &Path, destination: &Path) {
    std::fs::create_dir(destination).unwrap();
    for entry in std::fs::read_dir(source).unwrap() { let entry = entry.unwrap(); let target = destination.join(entry.file_name()); if entry.path().is_dir() { copy_directory(&entry.path(), &target); } else { std::fs::copy(entry.path(), target).unwrap(); } }
}

#[sqlx::test(migrations = "../db/migrations", fixtures("../db/fixtures/add_members.sql"))]
async fn declaration_sync_cli_acceptance(pool: PgPool) {
    let state = Shared::default();
    {
        let mut source = state.lock().unwrap();
        source.records.insert(1, record(1, 1, payer("Original Parent"), None));
        source.records.insert(2, record(2, 1, child("20"), Some(1)));
        let mut multiple = company("Earlier Company", "100").as_array().unwrap().clone();
        multiple.push(json!({"name":"Donors", "values":[[{"name":"Name", "value":"Removed Donor"}, {"name":"Value", "value":"90"}], [{"name":"Name", "value":"Retained Nested"}, {"name":"Value", "value":"30"}]]}));
        source.records.insert(3, record(3, 1, json!(multiple), None));
        source.records.insert(4, record(4, 1, company("Historical Company", "50"), None));
        source.records.insert(5, record(5, 1, child("7"), Some(999)));
        source.records.insert(6, record(6, 1, child("8"), Some(77)));
        source.records.insert(77, record(77, 9, payer("Outside parent"), None));
    }
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let application = Router::new().route("/Interests", axum::routing::get(interests)).with_state(state.clone());
    let server = tokio::spawn(async move { axum::serve(listener, application).await.unwrap(); });
    let temporary = tempfile::tempdir().unwrap();
    let data = temporary.path().join("data");
    let config = temporary.path().join("sync.yaml");
    std::fs::write(&config, format!("data_dir: {}\nbatch_size: 2\ncandidate_budget: 100000\ncutoff: 2026-10-12\ninterests_url: http://{address}/Interests\n", data.display())).unwrap();
    assert!(!cli(&pool, &config, "sync", None).await.status.success());
    assert!(state.lock().unwrap().requests.is_empty());
    success(cli(&pool, &config, "reconcile", None).await);
    let baseline = head(&pool).await;
    let baseline_manifest: Value = serde_json::from_slice(&std::fs::read(data.join(baseline.0.to_string()).join("capture.json")).unwrap()).unwrap();
    assert_eq!(baseline_manifest["scope"], json!([1, 2]));
    let original_child_time = baseline_manifest["declarations"]["2"]["declaration"]["fetched_at"].clone();
    {
        let mut source = state.lock().unwrap(); source.requests.clear();
        source.records.insert(1, record(1, 1, payer("Corrected Parent"), None));
        let mut corrected = record(3, 1, company("Current Company", "40"), None);
        let old = record(3, 1, company("Older Published Company", "999"), None)["versions"][0].clone();
        let mut old = old; old["register"] = json!({"id": 700, "publishedDate":"2025-01-01"});
        corrected["versions"].as_array_mut().unwrap().push(old);
        source.records.insert(3, corrected);
        source.records.insert(8, record(8, 2, company("New Company Alias", "60"), None));
        source.records.insert(9, record(9, 9, payer("Excluded outsider"), None));
        source.changed = [1, 3, 8, 9].into_iter().collect();
    }
    success(cli(&pool, &config, "sync", None).await);
    let delta = head(&pool).await;
    let manifest: Value = serde_json::from_slice(&std::fs::read(data.join(delta.0.to_string()).join("capture.json")).unwrap()).unwrap();
    assert_eq!(manifest["declarations"]["2"]["declaration"]["fetched_at"], original_child_time);
    assert_eq!(serde_json::from_str::<Value>(manifest["declarations"]["3"]["declaration"]["source_json"].as_str().unwrap()).unwrap()["versions"].as_array().unwrap().len(), 2);
    assert_eq!(manifest["exclusions"]["9"], 9);
    {
        let source = state.lock().unwrap();
        assert!(source.requests.iter().all(|request| !request.contains("MemberId=")));
        let hydrated = source.requests.iter().filter_map(|request| reqwest::Url::parse(&format!("http://localhost{request}")).unwrap().query_pairs().find(|(key, _)| key == "InterestIds").map(|(_, value)| value.into_owned())).collect::<BTreeSet<_>>();
        assert_eq!(hydrated, ["1", "3", "8", "77", "999"].into_iter().map(str::to_string).collect());
    }
    let fixed = sqlx::query!("SELECT e.source_declaration_id, e.amount::text AS amount, f.funder_name, e.unavailable_reason FROM exposed.funding_entries e LEFT JOIN exposed.funders f ON f.id = e.funder_id ORDER BY e.source_declaration_id").fetch_all(&pool).await.unwrap();
    assert_eq!(fixed.iter().find(|row| row.source_declaration_id == Some(2)).unwrap().funder_name.as_deref(), Some("Corrected Parent"));
    assert_eq!(fixed.iter().filter(|row| row.source_declaration_id == Some(3)).count(), 1);
    assert_eq!(fixed.iter().find(|row| row.source_declaration_id == Some(3)).unwrap().amount.as_deref(), Some("40"));
    assert!(!fixed.iter().any(|row| row.amount.as_deref() == Some("90") || row.amount.as_deref() == Some("999")));
    for id in [5, 6] { assert!(fixed.iter().find(|row| row.source_declaration_id == Some(id)).unwrap().unavailable_reason.is_some()); }
    let aliases = sqlx::query_scalar!("SELECT funder_alias FROM exposed.funder_aliases ORDER BY funder_alias").fetch_all(&pool).await.unwrap();
    assert!(aliases.contains(&"Historical Company".into()));
    assert!(aliases.contains(&"Older Published Company".into()));
    let expected = projection(&pool).await;
    let ids_before = sqlx::query_scalar!("SELECT id FROM exposed.funders ORDER BY id").fetch_all(&pool).await.unwrap();
    state.lock().unwrap().requests.clear();
    success(cli(&pool, &config, "sync", Some(delta.0)).await);
    assert_eq!(head(&pool).await, delta);
    assert!(state.lock().unwrap().requests.is_empty());
    assert!(!cli(&pool, &config, "load", None).await.status.success());
    state.lock().unwrap().changed.clear();
    success(cli(&pool, &config, "sync", None).await);
    let empty = head(&pool).await;
    assert_eq!(empty.1, delta.1 + 1);
    assert_eq!(projection(&pool).await, expected);
    assert_eq!(sqlx::query_scalar!("SELECT id FROM exposed.funders ORDER BY id").fetch_all(&pool).await.unwrap(), ids_before);
    assert!(!data.join(empty.0.to_string()).join("resolved").exists());
    for fault in ["http", "duplicate", "truncated", "total"] {
        { let mut source = state.lock().unwrap(); source.fault = Some(fault); source.changed = [1, 3, 8, 9].into_iter().collect(); }
        assert!(!cli(&pool, &config, "sync", None).await.status.success(), "fault {fault} must fail");
        assert_eq!(head(&pool).await, empty);
        assert_eq!(projection(&pool).await, expected);
    }
    state.lock().unwrap().fault = None;
    let stale = Uuid::now_v7();
    copy_directory(&data.join(empty.0.to_string()), &data.join(stale.to_string()));
    let path = data.join(stale.to_string()).join("capture.json");
    let mut stale_manifest: Value = serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap(); stale_manifest["run"] = json!(stale);
    std::fs::write(&path, serde_json::to_vec_pretty(&stale_manifest).unwrap()).unwrap();
    assert!(!cli(&pool, &config, "sync", Some(stale)).await.status.success());
    assert_eq!(head(&pool).await, empty);
    assert_eq!(projection(&pool).await, expected);
    success(cli(&pool, &config, "sync", Some(delta.0)).await);
    assert_eq!(head(&pool).await, empty);
    // A successful full-source omission retains the old complete record.
    state.lock().unwrap().records.remove(&4);
    success(cli(&pool, &config, "reconcile", None).await);
    assert_eq!(projection(&pool).await, expected);
    state.lock().unwrap().records.insert(4, record(4, 1, company("Historical Company", "50"), None));
    let member_rows = sqlx::query!("SELECT parliament_member_id, name, party_name FROM exposed.members ORDER BY parliament_member_id").fetch_all(&pool).await.unwrap();
    assert_eq!(member_rows.len(), 2);
    assert_eq!(member_rows[0].name, "John McDonnell");
    assert_eq!(member_rows[1].party_name, "Conservative");
    sqlx::query!("TRUNCATE exposed.declaration_sync_head, exposed.declaration_sync_runs, exposed.declaration_load_runs, exposed.funding_entries, exposed.declarations, exposed.funder_aliases, exposed.funders CASCADE").execute(&pool).await.unwrap();
    success(cli(&pool, &config, "reconcile", None).await);
    assert_eq!(projection(&pool).await, expected, "baseline plus delta must equal complete final evidence");
    server.abort();
}
